sealed interface UiState {
    data object Loading : UiState
    data class Success(val data: List<String>) : UiState
    data class Error(val message: String) : UiState
}

suspend fun fetchUserDetails(userId: String): Result<User> = withContext(Dispatchers.IO) {
    runCatching { apiClient.getUser(userId) }
}

class MainViewModel(private val repository: UserRepository) : ViewModel() {
    private val _uiState = MutableStateFlow<UiState>(UiState.Loading)
    val uiState: StateFlow<UiState> = _uiState.asStateFlow()

    fun loadData() {
        viewModelScope.launch {
            repository.getUsersFlow()
                .catch { emit(UiState.Error(it.message ?: "Error")) }
                .collect { _uiState.value = UiState.Success(it) }
        }
    }
}

fun <T> Flow<T>.throttleFirst(windowDuration: Long): Flow<T> = flow {
    var lastEmissionTime = 0L
    collect {
        val currentTime = System.currentTimeMillis()
        if (currentTime - lastEmissionTime >= windowDuration) {
            lastEmissionTime = currentTime
            emit(it)
        }
    }
}

data class Person(val name: String, val age: Int) {
    operator fun compareTo(other: Person): Int = this.age.compareTo(other.age)
}

